551	          // We use the asapScheduler here to prevent issues with trying to
552	          // update in the middle of a render. `reobserve` is kicked off in the
553	          // middle of a render and because RxJS emits values synchronously,
554	          // its possible for this `handleStoreChange` to be called in that same
555	          // render. This allows the render to complete before trying to emit a
556	          // new value.
557	          .pipe(observeOn(asapScheduler))
558	          .subscribe((result) => {
559	            const previous = resultData.current;
560	
561	            if (
562	              // Avoid rerendering if the result is the same
563	              equal(previous, result) &&
564	              // Force rerender if the value was emitted because variables
565	              // changed, such as when calling `refetch(newVars)` which returns
566	              // the same data when `notifyOnNetworkStatusChange` is `false`.
567	              equal(resultData.variables, observable.variables)
568	            ) {
569	              return;
570	            }
571	
572	            resultData.variables = observable.variables;
573	
574	            if (previous.data && !equal(previous.data, result.data)) {
575	              resultData.previousData = previous.data as TData;
576	            }
577	
578	            resultData.current = result;
579	            handleStoreChange();
580	          });
