583	        // This way, an existing subscription can be reused without an additional
584	        // request if "unsubscribe"  and "resubscribe" to the same ObservableQuery
585	        // happen in very fast succession.
586	        return () => {
587	          setTimeout(() => subscription.unsubscribe());
