607	  observable: ObsQueryWithMeta<TData, TVariables>,
608	  watchQueryOptions: Readonly<ApolloClient.WatchQueryOptions<TData, TVariables>>
609	) {
610	  "use no memo";
611	  if (
612	    observable[lastWatchOptions] &&
613	    !equal(observable[lastWatchOptions], watchQueryOptions)
614	  ) {
615	    // If skipToken was used to generate options, we won't know the correct
616	    // initialFetchPolicy until the hook is rerendered with real options, so we
617	    // set it the next time we get real options
618	    if (
619	      (observable[lastWatchOptions] as any)[fromSkipToken] &&
620	      !watchQueryOptions.initialFetchPolicy
621	    ) {
622	      (watchQueryOptions.initialFetchPolicy as any) =
623	        watchQueryOptions.fetchPolicy;
624	    }
625	    // Though it might be tempting to postpone this reobserve call to the
626	    // useEffect block, we need getCurrentResult to return an appropriate
627	    // loading:true result synchronously (later within the same call to
628	    // useQuery). Since we already have this.observable here (not true for
629	    // the very first call to useQuery), we are not initiating any new
630	    // subscriptions, though it does feel less than ideal that reobserve
631	    // (potentially) kicks off a network request (for example, when the
632	    // variables have changed), which is technically a side-effect.
633	    if (shouldReobserve(observable[lastWatchOptions], watchQueryOptions)) {
634	      observable.reobserve(watchQueryOptions);
635	    } else {
636	      observable.applyOptions(watchQueryOptions);
637	    }
638	
639	    // Make sure getCurrentResult returns a fresh ApolloQueryResult<TData>,
640	    // but save the current data as this.previousData, just like setResult
641	    // usually does.
642	    const result = observable.getCurrentResult();
643	
644	    if (!equal(result.data, resultData.current.data)) {
645	      resultData.previousData = (resultData.current.data ||
646	        (resultData.previousData as TData)) as TData;
647	    }
648	    resultData.current = result;
649	    resultData.variables = observable.variables;
650	  }
651	  observable[lastWatchOptions] = watchQueryOptions;
652	}
