import { ApolloProvider, useQuery } from "@apollo/client/react";
import { MockLink } from "@apollo/client/testing";

const CAR_QUERY = gql`
  query {
    cars {
      make
    }
  }
`;

it("ssr:false + skip:true hydrates without mismatch", async () => {
  const renders: Array<{
    loading: boolean;
    networkStatus: number;
    data: unknown;
  }> = [];

  function makeClient() {
    return new ApolloClient({
      cache: new InMemoryCache(),
      link: new MockLink([
        { request: { query: CAR_QUERY }, result: { data: { cars: [] } } },
      ]),
    });
  }

  const Component = () => {
    const { data, loading, networkStatus } = useQuery(CAR_QUERY, {
      ssr: false,
      skip: true,
    });
    renders.push({ loading, networkStatus, data });
    return <div>{String(loading)}</div>;
  };

  const serverClient = makeClient();
  const app = (client: ApolloClient) => (
    <ApolloProvider client={client}>
      <Component />
    </ApolloProvider>
  );

  const html = renderToString(app(serverClient));
  console.log("SERVER HTML:", html);
  console.log(
    "SERVER cache empty:",
    Object.keys(serverClient.cache.extract()).length === 0
  );

  const container = document.createElement("div");
  container.innerHTML = html;
  document.body.appendChild(container);

  const errors: unknown[] = [];
  const clientClient = makeClient();

  await act(async () => {
    hydrateRoot(container, app(clientClient), {
      onRecoverableError: (e) => errors.push(e),
    });
  });

  console.log("RECOVERABLE ERRORS:", errors.length);
  console.log("ALL RENDERS:", JSON.stringify(renders));
  console.log(
    "CLIENT cache empty:",
    Object.keys(clientClient.cache.extract()).length === 0
  );

  expect(errors).toHaveLength(0);
  for (const r of renders) {
    expect(r.loading).toBe(false);
    expect(r.networkStatus).toBe(NetworkStatus.ready);
    expect(r.data).toBeUndefined();
  }
  expect(NetworkStatus.ready).toBe(7);
});
